    # Simple backtracking for coloring
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n
    def solve(u):
        if u == n:
            return True

        used_colors = {colors[v] for v in adj[u] if colors[v] != -1}
        for c in range(5):
            if c not in used_colors:
                colors[u] = c
                if solve(u + 1):
                    return True
                colors[u] = -1
        return False

    return solve(0)

